import itertools
A = set(map(tuple, np.argwhere(inner==8)))
B = set(map(tuple, np.argwhere(out==8)))
def transforms(p):  # p in inner coords (9x10)
    r,c = p
    H, W = 9, 10
    return {
     'id': (r,c), 'rot90': (c, H-1-r), 'rot180': (H-1-r, W-1-c), 'rot270': (W-1-c, r),
     'flipH': (r, W-1-c), 'flipV': (H-1-r, c), 'transpose': (c, r), 'anti': (W-1-c, H-1-r)}
for name in transforms((0,0)):
    M = {transforms(p)[name] for p in A}
    if M == B: print("shape match:", name)
# markers
Am = {'2':(1,1),'4':(1,8),'3':(7,8)}
Bm = {'2':(8,7),'4':(1,7),'3':(1,1)}
for name in transforms((0,0)):
    if tuple(transforms(Am['2'])[name])==Bm['2'] and tuple(transforms(Am['4'])[name])==Bm['4'] and tuple(transforms(Am['3'])[name])==Bm['3']:
        print("marker match:", name)
# outer dot relative layout vs output marker layout
o = [(13,8,3),(13,14,4),(20,15,2)]
print("outer rel:", [(r-13,c-8,c) for r,c,c in o])
print("out markers rel:", Bm)

H,W = inner.shape
pred = np.zeros((W,H), int)
for r in range(H):
    for c in range(W):
        pred[c, H-1-r] = inner[r,c]
print(np.array_equal(pred, out))

diff = np.argwhere(pred!=out)
print(diff[:10])
for r,c in diff: print(r,c,pred[r,c],out[r,c])

pred2 = np.zeros((W,H), int)
for r in range(H):
    for c in range(W):
        pred2[W-1-c, H-1-r] = inner[r,c]
print(np.array_equal(pred2, out))
